mapper.select:
SELECT id, stocks_id, stocks_shortname, bar_start_time, bar_end_time,
       first_sample_time, last_sample_time, first_price, last_price,
       low_price, high_price, sample_count, duplicate_count, tail_gap_seconds,
       usable, quality_reason, build_version, source_max_history_id,
       deleted, create_time, update_time
FROM torn_stock_market_bar_15m
WHERE stocks_id IN

    #{stocksId}

  AND bar_start_time >= #{startTime}
  AND bar_start_time <= #{endTime}
  AND build_version = #{buildVersion}
  AND deleted = 0
ORDER BY stocks_id ASC, bar_start_time ASC

SELECT id, stocks_id, stocks_shortname, bar_start_time, bar_end_time, first_sample_time, last_sample_time, first_price, last_price, low_price, high_price, sample_count, duplicate_count, tail_gap_seconds, usable, quality_reason, build_version, source_max_history_id, deleted, create_time, update_time FROM ( SELECT b.*, ROW_NUMBER() OVER ( PARTITION BY b.stocks_id ORDER BY b.bar_start_time DESC, b.id DESC ) AS row_num FROM torn_stock_market_bar_15m b WHERE b.stocks_id IN
#{stocksId}
AND b.bar_start_time <= #{cutoffTime} AND b.bar_end_time >= #{minBarEndTime} AND b.build_version = #{buildVersion} AND b.usable = true AND b.last_price > 0 AND b.deleted = 0 ) latest WHERE row_num = 1 ORDER BY stocks_id ASC

SELECT stocks_id, MIN(bar_start_time) AS first_sample_time, MAX(bar_start_time) AS last_sample_time FROM torn_stock_market_bar_15m WHERE stocks_id IN
#{stocksId}
AND bar_start_time < #{cutoffTime} AND build_version = #{buildVersion} AND usable = true AND last_price > 0 AND deleted = 0 GROUP BY stocks_id ORDER BY stocks_id ASC

SELECT id, stocks_id, stocks_shortname, bar_start_time, bar_end_time, first_sample_time, last_sample_time, first_price, last_price, low_price, high_price, sample_count, duplicate_count, tail_gap_seconds, usable, quality_reason, build_version, source_max_history_id, deleted, create_time, update_time FROM torn_stock_market_bar_15m WHERE stocks_id IN
#{stocksId}
AND bar_start_time >= #{startTime} AND bar_start_time <= #{endTime} AND build_version = #{buildVersion} AND usable = true AND last_price > 0 AND deleted = 0 ORDER BY stocks_id ASC, bar_start_time ASC
